 "modules": {
  "open-and-set-up": {
   "id": "open-and-set-up",
   "name": "Open and set up",
   "objective": "Get the file in order: move around it by keyboard, name the tabs, delete the stale data, give the report its own sheet, set Excel up, color-code every sheet.",
   "story_beat": "The weekly reports are in. As usual, they’re a mess. || Five site managers, five spreadsheets, one workbook that ops pasted them into. There’s a tab still called Sheet2, last week’s export sitting next to this week’s, and a cost typed straight into a formula. The CFO wants one clean page out of this by Monday afternoon, so before you touch a number, get the file in order: name the tabs, delete the stale data, and give the report its own sheet.",
   "page_name": "The workbook, set up to standard"
  },
  "move-and-select": {
   "id": "move-and-select",
   "name": "Move and select",
   "objective": "Move and select by keyboard: Ctrl+Arrow and where it stops, Ctrl+End and Home, the selection set, rows, columns, widths and alignment, Go To Special.",
   "story_beat": "The CFO has questions about the weekly numbers. || How many days came through? Which columns did the managers send? Is every wash cost in? What’s written under the data? Every answer is a cell. Get to each one without scrolling (nobody who does this for a living scrolls), and then select the blocks you’ll be formatting next week.",
   "page_name": "The feed, answered"
  },
  "enter-edit-copy-fill": {
   "id": "enter-edit-copy-fill",
   "name": "Enter, edit, copy and fill",
   "objective": "Enter, edit, copy and fill: the missing day, the typos, the Report skeleton, Paste Special, Find and Replace, a timeline.",
   "story_beat": "A day is missing, and some of the figures are wrong. || Airport’s Saturday never came through, so the manager emailed the four numbers over. Type them in, fix the typos where they sit, then start the Report page by pulling the headers, the site list and the week label across from Raw and Inputs with the clipboard and the fill keys, so nothing gets typed twice.",
   "page_name": "The Report skeleton"
  },
  "structure": {
   "id": "structure",
   "name": "Structure",
   "objective": "Structure with formulas in play: rows and columns that keep the totals honest; the page’s columns; hide, group, freeze.",
   "story_beat": "Cedar Park opened this week. || That means a sixth site row for the Report, a margin column the CFO asked for and a stale column to get rid of, with a total that has to keep up with every edit. Then make the page readable: give the columns equal widths, fit the headers, tuck the working columns away and freeze the heads so they never scroll off.",
   "page_name": "The Report, reshaped"
  },
  "format": {
   "id": "format",
   "name": "Format",
   "objective": "Numbers a banker can read; fonts, fills, borders; alignment and titles; the style pass with F4.",
   "story_beat": "The numbers are right, so now make them readable. || The numbers are right, and your job still isn’t finished. The CFO answered from an iPhone, and the whole email was three words: pls fix, thx. You can have every number right and it counts for nothing if nobody can read the page, so set the thousands separators, line up the decimals, put the negatives in parentheses, bold the totals with a line on top and center the title across the page. Do each by hand once, then do the whole page in a single pass.",
   "page_name": "The Report, formatted"
  },
  "formulas": {
   "id": "formulas",
   "name": "Formulas",
   "objective": "SUM and its family, relative and absolute references, links across sheets, the errors and what they mean.",
   "story_beat": "Now make the page live. || Right now the Report is typed numbers, so if the feed changes you’d be retyping all of it. Link every figure back to Raw and Inputs and a fix upstream flows through on its own. This is the module where the page stops being a copy of the numbers and starts being a model of them.",
   "page_name": "The Report, live"
  },
  "present-and-audit": {
   "id": "present-and-audit",
   "name": "Present and audit",
   "objective": "The KPI page checked, print-ready and signed off: page one of the pack.",
   "story_beat": "Sign it off. || The CFO signs this page off and it goes into the data room as the company's current trading, the first thing a buyer's analyst opens. Check that the totals tie, that the conventions hold, that it prints on one page, and that nothing's typed where a link belongs. Then it goes in the pack.",
   "page_name": "Page one of the pack"
  },
  "project-and-assessment": {
   "id": "project-and-assessment",
   "name": "Project and assessment",
   "objective": "Build the weekly report end to end, then prove it against the clock; the assessment is the test-out.",
   "story_beat": "The CFO's next feed just landed. || New week, new feed, and nothing left to learn. You know every move this page needs. Time to execute: build it start to finish, then build it again on the clock. If you already knew all of this, the assessment is the test-out: pass it and the chapter is yours.",
   "page_name": "The weekly KPI report"
  },
  "number-formats": {
   "id": "number-formats",
   "name": "Number formats",
   "objective": "Number formats on a P&L: the desk number format and decimals by line, the sign convention stated once, currency and percent lines, real dates on the timeline.",
   "story_beat": "The P&L came out of the accounting system. || The owners have hired advisers to run the sale, and the first document is the book: the information memorandum that describes the company to buyers. Its financials section starts with three years of P&L, and what the accounting system exported is account codes in capitals, costs as positives and numbers to four decimal places. Before anyone reads it, the figures have to read like figures.",
   "page_name": "The P&L, formatted"
  },
  "custom-number-formats": {
   "id": "custom-number-formats",
   "name": "Custom number formats",
   "objective": "Custom number formats: the four-section code, units in the format, custom date codes for the timeline, conditions and hidden zeros.",
   "story_beat": "Every number on the page has to say what it is. || A buyer flips to the financials and reads margins, multiples and thousands without a legend, so the number format has to carry the unit. A format code can write k or m after a figure, show a zero as a dash, color a negative and turn a plain date into FY26E, with the value underneath untouched. This module is the format code, one section at a time.",
   "page_name": "The number-format set"
  },
  "remixes": {
   "id": "remixes",
   "name": "Remixes",
   "objective": "Chapter 1’s challenges re-clothed in this chapter’s material: the same keys on a new sheet, so old skills stay warm.",
   "story_beat": "",
   "page_name": "Old skills on the new page"
  }
 },
